from codecs import decode


def decode_object_id(object_id):
    """
    Decodes list of bytes UUID to string
    :param object_id: UUID bytes type object
    :return: UUID string
    """
    try:
        return decode(object_id)
    except UnicodeDecodeError:
        return "ObjectId:" + "".join([format(byte, "02X") for byte in bytearray(object_id)])
